ir_data = namedtuple('ir_data', ['rtt', 'sync_proposal',
                                 'proposal_out_of_sync_counter', 'proposal_in_sync_counter',
                                 'sync_state',
                                 'out_of_sync_counter', 'in_sync_counter'])


@register_message
class BrowserRakeStartIRMeasurementsReq(RequestMessage):
    id = 0x1b13

    _fields_ = [
        ('header', SMessageHeader),
        ('userId', u32),
        ('radioLinkId', u32),
        ('measurementPeriod', u32),
        ('irLength', u32),
        ('typeOfMeas', i32),
        ('rachCellIndex', i32)
    ]


@register_message
class BrowserRakeStopIRMeasurementsReq(RequestMessage):
    id = 0x1b14

    _fields_ = [
        ('header', SMessageHeader),
        ('userId', u32),
        ('radioLinkId', u32),
        ('measurementPeriod', u32),
        ('rachCellIndex', i32)
    ]


@register_message
class BrowserRakeIRMeasurementInd(ResponseMessage):
    id = 0x1b15

    _fields_ = [
        ('header', SMessageHeader),
        ('userId', u32),
        ('radioLinkId', u32),
        ('antennaId', u32),
        ('delay', i32 * 2),
        ('fingerCount', u32),
        ('fingers', i32 * 8),
        ('irLength', u32),
        ('irVector', u32 * 192),
        ('roundTripTime', u32),
        ('allocatedFingerCount', u32),
        ('allocatedFingerDelays', i32 * 8),
        ('allocatedFingerPowers', u32 * 8),
        ('syncState', u32),
        ('syncProposal', u32),
        ('syncStateInSyncCounter', u32),
        ('syncProposalInSyncCounter', u32),
        ('syncStateOutOfSyncCounter', u32),
        ('syncProposalOutOfSyncCounter', u32)
    ]


class SRakeTiming(Structure):
    _fields_ = [
        ('frame', i32),
        ('slot', i32),
        ('chip', i32),
        ('chip4th', i32),
    ]


@register_trace_ind
@register_message
class BrowserRakeRachIRMeasurementInd(ResponseMessage):
    id = 0x1b33

    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('sfn', SRakeTiming),
        ('antennaIndex', u32),
        ('fingerCount', u32),
        ('fingers', i32 * 4),
        ('irLength', u32),
        ('totalIrLength', u32),
        ('irIndex', u32),
        ('irVector', u16 * 256),
        ('rachCellIndex', i32)
    ]


class StartRakeIRMeas(Query):
    """
    StartRakeIRMeas and StartRakeIRMeas don't expect any response!!! For now will go with resp=None

    typeOfMeas:
    0 – Starts ir measurement reporting to browser, but only reports summed ir
    1 – Starts ir measurement reporting to browser, but reports the antenna wise ir
    """
    def __init__(self, req, resp=None):
        super(StartRakeIRMeas, self).__init__(req, resp)

    def fill_req_msg(self, user_id, radio_link_id, meas_period, summed):
        # type: (int, int, int) -> None
        self.req_msg.userId = user_id
        self.req_msg.radioLinkId = radio_link_id
        self.req_msg.measurementPeriod = meas_period
        self.req_msg.irLength = 4
        self.req_msg.typeOfMeas = 0 if summed else 1

    def _handle_response(self):
        """
        No response is expected
        """
        pass


class StopRakeIRMeas(Query):
    """
    StartRakeIRMeas and StartRakeIRMeas don't expect any response!!!
    """

    def __init__(self, req, resp=None):
        super(StopRakeIRMeas, self).__init__(req, resp)

    def fill_req_msg(self, user_id, radio_link_id):
        # type: (int, int) -> None
        self.req_msg.userId = user_id
        self.req_msg.radioLinkId = radio_link_id

    def _handle_response(self):
        """
        No response is expected
        """
        pass


class RakeIRMeasSink(BrowserGeneralReportIndSink):
    """
    Apparently, it takes time  between sending start message and the first ind as
    the response - hence the wait event that is monitored by the RakeIRMeasCollector
    """
    def __init__(self, cookie):
        super(RakeIRMeasSink, self).__init__(cookie)
        self.received_measurement_event = threading.Event()

    def digest(self, byte_stream):
        self.all_inds.append(byte_stream)
        self.received_measurement_event.set()


class RakeIRQueryManager(BasicQueryManager):
    def __init__(self, query, connection):
        super(RakeIRQueryManager, self).__init__(query, connection)

    def _register(self):
        """if we don't expect any responses, we don't need to set cookie or register the manager"""
        pass


class RakeIRMeasCollector(BaseMeasurementCollector):
    def __init__(self, connection):
        super(RakeIRMeasCollector, self).__init__(connection)
        self.user_id = None
        self.radio_link_id = None
        self.meas_period = None
        self.summed = None

    def find_target_board_cpu(self, cell_id):  # noqa: C901
        """
        1. Find candidate (board, cpu) pairs on which RTT value (Impulse Response) can be measured
        2. Among candidate pairs find the one on with User is allocated
        3. Get Radio Link ID
        4. Assert that requested cell is actually handled by the found (board, cpu)
        """
        message_id = 0x1B13  # Impulse Response

        candidate_board_and_cpu_ids = ServiceInterface(self.connection).get_board_cpu_pairs_with_given_service_or_message(message_id)

        user = SBrowserUser()
        board_cpu_user_hsdpa, board_cpu_user_dch = None, None
        target_board, target_cpu = None, None

        for board, cpu in candidate_board_and_cpu_ids:
            trial_cell_ids = CellListInterface(self.connection).get_cell_ids(board, cpu)
            if cell_id in trial_cell_ids:
                users = UserListInterface(self.connection).get_users(board, cpu)
                hsdpa_user = UserListInterface(self.connection).filter_out_single_user_with_type(EUserType_Ver2.EUserType_Ver2_Hspa, users)
                dch_user = UserListInterface(self.connection).filter_out_single_user_with_type(EUserType_Ver2.EUserType_Ver2_Dch, users)
                if hsdpa_user:
                    board_cpu_user_hsdpa = (board, cpu, hsdpa_user)
                if dch_user:
                    board_cpu_user_dch = (board, cpu, dch_user)

        if board_cpu_user_hsdpa:
            target_board, target_cpu, user = board_cpu_user_hsdpa
        elif board_cpu_user_dch:
            target_board, target_cpu, user = board_cpu_user_dch

        if not target_cpu:
            LOGGER.error('Could not determine board and cpu for getting RRT value for cell {}'.format(cell_id))
            return

        LOGGER.info('Found target board and cpu: 0x{:x}{:x}'.format(target_board, target_cpu))
        user_id = user.userId
        LOGGER.debug('Got user: {}'.format(user))

        # radio link
        radio_link_ids = RadioLinkListInterface(self.connection).get_radio_link_ids(target_board, target_cpu, user_id)
        try:
            radio_link_id = radio_link_ids[0]
            LOGGER.debug('Got radio link: {}'.format(radio_link_id))
        except IndexError:
            LOGGER.error('No radio link for 0x{:x}{:x}'.format(target_board, target_cpu))
            return

        self.board = target_board
        self.cpu = target_cpu
        self.user_id = user_id
        self.radio_link_id = radio_link_id

    def prepare_query_managers(self):
        # type: () -> RakeIRMeasCollector
        if not self.board:
            return
        board, cpu = self.board, self.cpu
        start_query = StartRakeIRMeas(BrowserRakeStartIRMeasurementsReq(board, cpu))
        start_query.fill_req_msg(self.user_id, self.radio_link_id, self.meas_period, self.summed)

        stop_query = StopRakeIRMeas(BrowserRakeStopIRMeasurementsReq(board, cpu))
        stop_query.fill_req_msg(self.user_id, self.radio_link_id)

        self.start_qm = RakeIRQueryManager(start_query, self.connection)
        self.stop_qm = RakeIRQueryManager(stop_query, self.connection)
        self.ind_m = RakeIRMeasSink(cookie=(BrowserRakeIRMeasurementInd.id, 0, 0))  # no contextId or procedureId

    def wait_for_measurements(self, timeout=30):
        self.ind_m.received_measurement_event.wait(timeout)


def _prepare_rtt_value_collector(cell_id, connection):
    meas_period = 100  # ms
    type_of_meas = 0

    collector = RakeIRMeasCollector(connection)
    collector.set_parameters(
        meas_period=meas_period,
        summed=type_of_meas
    )
    collector.find_target_board_cpu(cell_id)
    collector.prepare_query_managers()
    return collector


class RakeIRInterface(object):

    def __init__(self, connection):
        self.connection = connection

    def get_rtt_value(self, cell_id):
        # type: (int) -> int

        collector = _prepare_rtt_value_collector(cell_id, self.connection)
        if collector:
            collector.start()
            collector.wait_for_measurements(timeout=30)
            collector.stop()

        if collector.ind_m:
            LOGGER.debug('Received {} inds'.format(len(collector.ind_m.all_inds)))
        else:
            LOGGER.debug('No inds collected')
            return -1

        data = self.process_ir_measurements(collector.ind_m.all_inds)

        headers = ['RTT', 'Sync proposal', 'Out-of-sync count proposal', 'In-sync count proposal', 'Sync state',
                   'Out-of-sync count', 'In-sync count']
        values = list(data)
        values[1] = 'InSync' if data.sync_proposal else 'OutOfSync'
        values[4] = 'Found' if data.sync_state else 'Lost'
        LOGGER.info(tabulate([values], headers=headers, tablefmt="fancy_grid"))

        try:
            return int(data.rtt)
        except AttributeError:
            return -2

    def process_ir_measurements(self, all_inds):
        # type: (List[bytearray]) -> List[namedtuple]
        accumulated_sync_proposal_out_of_sync_counter = 0
        accumulated_sync_proposal_in_sync_counter = 0
        accumulated_sync_out_of_sync_counter = 0
        accumulated_sync_in_sync_counter = 0

        for byte_stream in all_inds:
            ir = BrowserRakeIRMeasurementInd().deserialize(byte_stream)

            # delay_in_chip = ir.delay[1]
            # if ir.delay[0] == 0:
            #     unit_in_chip = 0.25    # 1/4 chip
            #     window_in_chip = ir.irLenght * unit_in_chip
            # else:
            #     unit_in_chip = ir.delay[0] / float(ir.irLenght)  # 1/4 chip
            #     window_in_chip = ir.delay[0]
            #
            # ir_length = ir.irLength
            # ir_vector_u16 = u16 * (ir_length * 2)
            # ir_vector_u16 = ir_vector_u16.from_buffer_copy(buffer(ir.irVector)[:])
            # x_list = [delay_in_chip + i * unit_in_chip for i in ir_vector_u16]

            accumulated_sync_proposal_out_of_sync_counter += ir.syncProposalOutOfSyncCounter
            accumulated_sync_proposal_in_sync_counter += ir.syncProposalInSyncCounter
            accumulated_sync_out_of_sync_counter += ir.syncStateOutOfSyncCounter
            accumulated_sync_in_sync_counter += ir.syncStateInSyncCounter

        ir = BrowserRakeIRMeasurementInd().deserialize(all_inds[0])
        rtt = ((ir.roundTripTime & 0xFF) << 24) | ((ir.roundTripTime & 0xFF00) << 8) | \
              ((ir.roundTripTime & 0xFF0000) >> 8) | ((ir.roundTripTime & 0xFF000000) >> 24)
        sync_proposal = ir.syncProposal
        proposal_out_of_sync_counter = accumulated_sync_proposal_out_of_sync_counter
        proposal_in_sync_counter = accumulated_sync_proposal_in_sync_counter
        sync_state = ir.syncState
        out_of_sync_counter = accumulated_sync_out_of_sync_counter
        in_sync_counter = accumulated_sync_in_sync_counter

        data = ir_data(
            rtt=rtt,
            sync_proposal=sync_proposal,
            proposal_out_of_sync_counter=proposal_out_of_sync_counter,
            proposal_in_sync_counter=proposal_in_sync_counter,
            sync_state=sync_state,
            out_of_sync_counter=out_of_sync_counter,
            in_sync_counter=in_sync_counter
        )

        return data
